window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8fe25899f2c52b23"]={"versions": [{"id": "FIG-8fe25899f2c52b23", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm definiert die strukturelle Zerlegung des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und die zugehörigen Konfigurationsparameter im BSW-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral</code> vom Metatyp <code>EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über die Komposition <code>+container</code> dem Modul <code>J1939Rm</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmDevErrorDetect</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmMainFunctionPeriod</code>: <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0.001</code>, <code>max = 0.255</code></li>\n<li><code>J1939RmSupportAckIndication</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmTxConfirmationTimeout</code>: <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0.0</code>, <code>max = 65.535</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführungszeit der Hauptfunktion (<code>J1939RmMainFunctionPeriod</code>), Timeouts für Bestätigungsmeldungen (<code>J1939RmTxConfirmationTimeout</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu instanziieren (<code>1..1</code>). Die Parameter aktivieren bzw. deaktivieren optionale Modulfunktionen (Default Error Detection, Versions-API, Indication- und Transmission-Pfade) zur Compile-Zeit und setzen numerische Schranken für Timer und Zykluszeiten.</p>"}, {"id": "FIG-19401020e98fc2b6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm definiert die strukturelle Zerlegung des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und die zugehörigen Konfigurationsparameter im BSW-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral</code> vom Metatyp <code>EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über die Komposition <code>+container</code> dem Modul <code>J1939Rm</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmDevErrorDetect</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmMainFunctionPeriod</code>: <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0.001</code>, <code>max = 0.255</code></li>\n<li><code>J1939RmSupportAckIndication</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmTxConfirmationTimeout</code>: <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0.0</code>, <code>max = 65.535</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführungszeit der Hauptfunktion (<code>J1939RmMainFunctionPeriod</code>), Timeouts für Bestätigungsmeldungen (<code>J1939RmTxConfirmationTimeout</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu instanziieren (<code>1..1</code>). Die Parameter aktivieren bzw. deaktivieren optionale Modulfunktionen (Default Error Detection, Versions-API, Indication- und Transmission-Pfade) zur Compile-Zeit und setzen numerische Schranken für Timer und Zykluszeiten.</p>"}, {"id": "FIG-dbe3c6612fa8f096", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm definiert die strukturelle Zerlegung des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und die zugehörigen Konfigurationsparameter im BSW-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral</code> vom Metatyp <code>EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über die Komposition <code>+container</code> dem Modul <code>J1939Rm</code> (<code>EcucModuleDef</code>, Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi</code>: <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmDevErrorDetect</code>: <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmMainFunctionPeriod</code>: <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = INF</code></li>\n<li><code>J1939RmSupportAckIndication</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequest2</code>: <code>EcucBooleanParamDef</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführung (<code>J1939RmMainFunctionPeriod</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request-, Request2- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu konfigurieren (<code>1..1</code>). <code>J1939RmVersionInfoApi</code> und <code>J1939RmDevErrorDetect</code> besitzen normative Standardwerte (<code>defaultValue = false</code>). <code>J1939RmMainFunctionPeriod</code> deckt den Bereich ab 0 ohne obere Schranke ab (<code>max = INF</code>). Der Parameter <code>J1939RmSupportRequest2</code> schaltet die Unterstützung für Request2-Nachrichten.</p>"}, {"id": "FIG-7cad8f32bcf5e7c9", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm definiert die strukturelle Zerlegung des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und die zugehörigen Konfigurationsparameter im BSW-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral: EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über die Komposition <code>+container</code> dem Modul <code>J1939Rm: EcucModuleDef</code> (Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmDevErrorDetect:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmMainFunctionPeriod:</code> <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = INF</code></li>\n<li><code>J1939RmSupportAckIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequest2:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmGatewaySupport:</code> <code>EcucBooleanParamDef</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführung (<code>J1939RmMainFunctionPeriod</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request-, Request2- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu konfigurieren (<code>1..1</code>). Neben Versions- und Entwicklungsfehler-APIs (Standardwert <code>false</code>) und Request2 wird über <code>J1939RmGatewaySupport</code> die Gateway-Funktionalität des Request Managers konfiguriert.</p>"}, {"id": "FIG-6517911fd8c66993", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm definiert die strukturelle Zerlegung des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und die zugehörigen Konfigurationsparameter im BSW-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral: EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über die Komposition <code>+container</code> dem Modul <code>J1939Rm: EcucModuleDef</code> (Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmDevErrorDetect:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmMainFunctionPeriod:</code> <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = INF</code></li>\n<li><code>J1939RmSupportAckIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequest2:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmGatewaySupport:</code> <code>EcucBooleanParamDef</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführung (<code>J1939RmMainFunctionPeriod</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request-, Request2- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu konfigurieren (<code>1..1</code>). Neben Versions- und Entwicklungsfehler-APIs (Standardwert <code>false</code>) und Request2 wird über <code>J1939RmGatewaySupport</code> die Gateway-Funktionalität des Request Managers konfiguriert.</p>"}, {"id": "FIG-0c8dbb6051886b0d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm definiert die strukturelle Zerlegung des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und die zugehörigen Konfigurationsparameter im BSW-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral: EcucParamConfContainerDef</code> (Kardinalität 1..1), untergeordnet unter <code>J1939Rm: EcucModuleDef</code> (0..1) via <code>+container</code>.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert die Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li>Vollständig lesbar: <code>J1939RmVersionInfoApi:</code> (<code>EcucBooleanParamDef</code>, <code>defaultValue = false</code>), <code>J1939RmMainFunctionPeriod:</code> (<code>EcucFloatParamDef</code>, <code>min = 0</code>, <code>max = INF</code>), <code>J1939RmSupportAckIndication:</code>, <code>J1939RmSupportRequestIndication:</code>, <code>J1939RmSupportTimeoutSupervision:</code> und <code>J1939RmGatewaySupport:</code> (jeweils <code>EcucBooleanParamDef</code>).</li>\n<li>Durch fehlerhaften Bildbeschnitt am rechten Rand unvollständig sichtbar: <code>J1939RmDevErrorDetect</code> (abgeschnitten als <code>J1939... / Ecuc... / de...</code>), <code>J1939RmSupportAckTransmission</code> (abgeschnitten als <code>J1939RmSuppo... / EcucBoole...</code>), <code>J1939RmSupportRequestTransmission</code> (abgeschnitten als <code>J1939RmSupportR... / EcucBoole...</code>) und <code>J1939RmSupportRequest2</code> (abgeschnitten als <code>J1939RmSup... / EcucBoole...</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführung (<code>J1939RmMainFunctionPeriod</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request-, Request2- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation des Containers <code>J1939RmGeneral</code> (1..1). Aufgrund eines Darstellungs-/Beschnittfehlers im Dokument sind die Parameternamen und Typdefinitionen der rechten Spalte nur fragmentarisch im Diagramm dokumentiert.</p>"}, {"id": "FIG-aa5df73af9f1c29b", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm stellt in einem vertikal ausgerichteten Layout die Struktur des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und dessen Parameterdefinitionen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral: EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über eine vertikale Kompositionsbeziehung <code>+container</code> dem darüber angeordneten Modul <code>J1939Rm: EcucModuleDef</code> (Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende vollständig sichtbare Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmDevErrorDetect:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmMainFunctionPeriod:</code> <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = INF</code></li>\n<li><code>J1939RmSupportAckIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequest2:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmGatewaySupport:</code> <code>EcucBooleanParamDef</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführung (<code>J1939RmMainFunctionPeriod</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request-, Request2- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu konfigurieren (<code>1..1</code>). Neben Versions- und Entwicklungsfehler-APIs (Standardwert <code>false</code>) und Request2 wird über <code>J1939RmGatewaySupport</code> die Gateway-Funktionalität des Request Managers konfiguriert. Alle Parameterdefinitionen sind im Diagramm vollständig und unbeschnitten spezifiziert.</p>"}, {"id": "FIG-d44c42d09335d99e", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmodells (ECUC Parameter Definition) für das BSW-Modul SAE J1939 Request Manager (<code>J1939Rm</code>). Das Diagramm stellt in einem vertikal ausgerichteten Layout die Struktur des allgemeinen Konfigurationscontainers <code>J1939RmGeneral</code> und dessen Parameterdefinitionen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Definitionscontainer <code>J1939RmGeneral: EcucParamConfContainerDef</code> mit Multiplizität 1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>). Er ist über eine vertikale Kompositionsbeziehung <code>+container</code> dem darüber angeordneten Modul <code>J1939Rm: EcucModuleDef</code> (Kardinalität 0..1) untergeordnet.</p>\n<p class=\"fig-p\"><code>J1939RmGeneral</code> aggregiert über Kompositionsbeziehungen <code>+parameter</code> folgende vollständig sichtbare Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>J1939RmVersionInfoApi:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmDevErrorDetect:</code> <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code></li>\n<li><code>J1939RmMainFunctionPeriod:</code> <code>EcucFloatParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = INF</code></li>\n<li><code>J1939RmSupportAckIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportAckTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestIndication:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequestTransmission:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportTimeoutSupervision:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmSupportRequest2:</code> <code>EcucBooleanParamDef</code></li>\n<li><code>J1939RmGatewaySupport:</code> <code>EcucBooleanParamDef</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Parameter steuern die zyklische Ausführung (<code>J1939RmMainFunctionPeriod</code>) sowie das Schalten von Funktionspfaden für Acknowledgment-, Request-, Request2- und Timeout-Überwachungsabläufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation für Implementierer des J1939Rm-Moduls. Der Container <code>J1939RmGeneral</code> ist obligatorisch genau einmal zu konfigurieren (<code>1..1</code>). Neben Versions- und Entwicklungsfehler-APIs (Standardwert <code>false</code>) und Request2 wird über <code>J1939RmGatewaySupport</code> die Gateway-Funktionalität des Request Managers konfiguriert. Alle Parameterdefinitionen sind im Diagramm vollständig und unbeschnitten spezifiziert.</p>"}], "trans": [{"from": "FIG-8fe25899f2c52b23", "to": "FIG-19401020e98fc2b6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-19401020e98fc2b6", "to": "FIG-dbe3c6612fa8f096", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>J1939RmTxConfirmationTimeout</code> entfällt.</li>\n<li>Neuer Konfigurationsparameter <code>J1939RmSupportRequest2</code> vom Typ <code>EcucBooleanParamDef</code> hinzugefügt.</li>\n<li>Parameter <code>J1939RmVersionInfoApi</code>: Standardwert <code>defaultValue = false</code> hinzugefügt.</li>\n<li>Parameter <code>J1939RmDevErrorDetect</code>: Standardwert <code>defaultValue = false</code> hinzugefügt.</li>\n<li>Parameter <code>J1939RmMainFunctionPeriod</code>: Wertebereichsgrenzen von <code>min = 0.001</code>, <code>max = 0.255</code> geändert auf <code>min = 0</code>, <code>max = INF</code>.</li>\n</ul>"}, {"from": "FIG-dbe3c6612fa8f096", "to": "FIG-7cad8f32bcf5e7c9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Konfigurationsparameter <code>J1939RmGatewaySupport</code> vom Typ <code>EcucBooleanParamDef</code> im Container <code>J1939RmGeneral</code> hinzugefügt.</li>\n<li>Redaktionelle Anpassung der Schreibweise: Doppelpunkte bei Klassennamen/Typisierungen ohne führendes Leerzeichen (<code>J1939Rm: EcucModuleDef</code>, <code>J1939RmGeneral: EcucParamConfContainerDef</code> etc.).</li>\n</ul>"}, {"from": "FIG-7cad8f32bcf5e7c9", "to": "FIG-6517911fd8c66993", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6517911fd8c66993", "to": "FIG-0c8dbb6051886b0d", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Fehlerhafter Bildausschnitt: Die rechte Spalte der Konfigurationsparameter (<code>J1939RmDevErrorDetect</code>, <code>J1939RmSupportAckTransmission</code>, <code>J1939RmSupportRequestTransmission</code>, <code>J1939RmSupportRequest2</code>) ist am rechten Bildrand abgeschnitten.</li>\n</ul>"}, {"from": "FIG-0c8dbb6051886b0d", "to": "FIG-aa5df73af9f1c29b", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Vollständiger Bildausschnitt wiederhergestellt; die abgeschnittenen Parameter der rechten Spalte sind wieder vollständig sichtbar.</li>\n<li>Vertikales Layout geändert: Das Modul-Element <code>J1939Rm: EcucModuleDef</code> ist direkt oberhalb des Containers <code>J1939RmGeneral: EcucParamConfContainerDef</code> platziert; die Kompositionslinie verläuft vertikal.</li>\n</ul>"}, {"from": "FIG-aa5df73af9f1c29b", "to": "FIG-d44c42d09335d99e", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>J1939RmGeneral</code>: Typbezeichnung von <code>EcucParamConfContainerDef</code> korrigiert zu <code>EcucParamConfContainerDef</code> bzw. in der vorherigen Fassung stand <code>EcucParamConfContainerDef</code>, in der neuen Fassung steht <code>EcucParamConfContainerDef</code>? Moment!</li>\n</ul>"}]};
